import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Create plane mesh
  const geometry = new PlaneGeometry(4, 3);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Render text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: (item.typography && item.typography.fontSize) || 39,
      color: (config.visual?.colors && config.visual.colors.paper) || '#e8ecf2',
      align: 'center',
    });
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives
  const primitiveHandles = [];
  for (const prim of config.cinematicPrimitives || []) {
    const handle = ctx.primitives[prim.name](root, prim.params);
    primitiveHandles.push(handle);
  }

  // Entrance animation (rise‑in)
  const entranceTl = gsap.timeline({ paused: true });
  entranceTl.from(mesh.position, {
    y: mesh.position.y + 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  entranceTl.play();

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material & geometry
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();

    // Kill GSAP timelines
    entranceTl.kill();

    // Cleanup primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }
  };

  return root;
}
